module.exports = function(RED) {
  const DataStorage = require('kumva-insights/utils/data-storage');

  function getPendingVoiceResponses(node) {
    let map = node.context().global.get('kumvaPendingVoiceResponses');
    if (!map) {
      map = new Map();
      node.context().global.set('kumvaPendingVoiceResponses', map);
    }
    return map;
  }

  function KumvaEndFlowNode(config) {
    RED.nodes.createNode(this, config);
    const node = this;
    const dataStorage = new DataStorage();

    node.on('input', async function(msg) {
      try {
        const sessionManager = node.context().global.get('sessionManager');

        const sessionKey = msg.sessionKey;
        if (!sessionKey) {
          return node.error('No sessionKey or sessionId');
        }

        const sessionResult = await sessionManager.getSession(sessionKey);
        if (!sessionResult.exists) {
          return node.error(`Session not found: ${sessionKey}`);
        }

        const sessionData = sessionResult.data;
        const summary = {
          sessionKey,
          campaignId: sessionData.campaignId,
          phoneNumber: sessionData.phoneNumber,
          campaignType: sessionData.serviceType,
          status: 'completed',
          startedAt: sessionData.createdAt,
          completedAt: new Date().toISOString(),
          duration: new Date() - new Date(sessionData.createdAt)
        };

        if (config.storeReport) {
          await dataStorage.saveCampaignReport(sessionData.campaignId, summary);
        }

        if (config.sendNotification && config.notificationUrl) {
          try {
            await fetch(config.notificationUrl, {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify(summary)
            });
          } catch (e) {
            node.warn(`Notification failed: ${e.message}`);
          }
        }

        // If this is an IVR session that still has an open Africa's Talking
        // webhook response waiting, finish it with a Hangup so the call ends
        // cleanly instead of timing out on their end. No-op for SMS.
        const pendingResponses = getPendingVoiceResponses(node);
        const pendingRes = pendingResponses.get(sessionKey);
        if (pendingRes) {
          pendingRes.set('Content-Type', 'text/xml');
          pendingRes.send('<?xml version="1.0" encoding="UTF-8"?><Response><Hangup/></Response>');
          pendingResponses.delete(sessionKey);
        }

        if (config.deleteSession) {
          await sessionManager.deleteSession(sessionKey);
        }

        if (config.cleanupResponses) {
          await dataStorage.deleteSessionResponses(sessionKey);
        }

        console.log('[KUMVA][EndFlow] session-closed', JSON.stringify({ sessionKey, summary }));

        const outputMsg = {
          ...msg,
          sessionKey,
          summary,
          flowStatus: 'completed'
        };

        node.status({ fill: 'green', shape: 'dot', text: 'Completed' });
        node.send(outputMsg);

      } catch (error) {
        console.error('[KUMVA][EndFlow] error', error);
        node.error(`EndFlow: ${error.message}`);
        node.status({ fill: 'red', shape: 'ring', text: 'Error' });
      }
    });

    node.status({ fill: 'yellow', shape: 'ring', text: 'Ready' });
  }

  RED.nodes.registerType('kumva-end-flow', KumvaEndFlowNode);
};